const rows = Array.from({ length: 2_500 }, (_, index) => ({
  id: `activity-${index}`,
  name: `Activity ${index % 80}`,
  durationMs: 900 + ((index * 37) % 9_100),
}))

const durationFormatter = new Intl.NumberFormat('en-US', {
  minimumFractionDigits: 3,
  maximumFractionDigits: 3,
})

export function sourceRows() {
  return rows
}

export function totalDurationMs(items = rows) {
  return items.reduce((total, row) => total + row.durationMs, 0)
}

export function renderRows(items = rows) {
  return items.map((row) => ({
    id: row.id,
    label: `${row.name}: ${durationFormatter.format(row.durationMs / 1_000)} s`,
  }))
}

import assert from 'node:assert/strict'
import { test } from 'node:test'
import { renderRows, sourceRows, totalDurationMs } from '../src/report.mjs'

test('duration labels and row order match the reviewed export', () => {
  const source = sourceRows()
  const total = totalDurationMs()
  const rendered = renderRows()
  assert.equal(rendered.length, source.length)
  assert.equal(rendered[0].label, 'Activity 0: 0.900 s')
  assert.equal(rendered[1].label, 'Activity 1: 0.937 s')
  assert.equal(rendered.at(-1).label, 'Activity 19: 2.363 s')
  assert.deepEqual(
    rendered.map((row) => row.id),
    source.map((row) => row.id),
  )
  assert.equal(
    total,
    source.reduce((sum, row) => sum + row.durationMs, 0),
  )
  assert.equal(total, 13_451_750)
  assert.equal(totalDurationMs(), total)
})

import { performance } from 'node:perf_hooks'
import { renderRows } from './src/report.mjs'

for (let index = 0; index < 2; index += 1) renderRows()
const samplesMs = []
for (let index = 0; index < 7; index += 1) {
  const start = performance.now()
  const rows = renderRows()
  if (rows.length !== 2_500) throw new Error('render changed the row count')
  samplesMs.push(Number((performance.now() - start).toFixed(3)))
}
const ordered = [...samplesMs].sort((left, right) => left - right)
console.log(JSON.stringify({ samplesMs, medianMs: ordered[Math.floor(ordered.length / 2)] }, null, 2))
